flow.typescript:
// D2 · Part 0~6 · 오늘의 흐름 전체 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d02_flow.ts
//   소리 → 숫자 → 샘플링 → 양자화 → 채널 → 파일 크기 → 음성 모델용 전처리를 한 번에 확인
import { readFileSync, statSync, writeFileSync } from "node:fs";
const SR = 16000; // 음성 모델 표준: 1초에 16,000번 측정 (16kHz)

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}


function tone(freq: number, sec: number = 1, sr: number = SR, amp: number = 0.5, phase: number = 0): Float32Array {
  // freq Hz 순수한 소리(사인파) x(t) = A sin(2 pi f t + phi)
  const y = new Float32Array(Math.floor(sr * sec));
  for (let i = 0; i < y.length; i++) y[i] = amp * Math.sin(2 * Math.PI * freq * (i / sr) + phase);
  return y;
}


function mulberry32(seed: number): () => number {
  // 씨앗(seed)이 같으면 늘 같은 난수 순서 (0 이상 1 미만)
  let a = seed >>> 0;
  return (): number => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function gauss(rnd: () => number): number {
  // 표준 정규분포 난수 (Box-Muller)
  return Math.sqrt(-2 * Math.log(rnd() + 1e-12)) * Math.cos(2 * Math.PI * rnd());
}


function synthVoice(seconds: number = 2, f0: number = 140, seed: number = 0, sr: number = SR): Float32Array {
  // 말소리 비슷한 합성 신호(mono): 기본음 + 배음 5개 + 음절 모양 세기 + 약한 잡음
  const n = Math.floor(seconds * sr);
  const y = new Float32Array(n);
  const rnd = mulberry32(seed);
  let phase = 0;
  let peak = 1e-9;
  for (let i = 0; i < n; i++) {
    const t = i / sr;
    phase += (2 * Math.PI * f0 * (1 + 0.05 * Math.sin(2 * Math.PI * 0.7 * t))) / sr;
    let v = 0;
    for (let k = 1; k <= 5; k++) v += Math.sin(k * phase) / k;
    y[i] = v * Math.sqrt(Math.max(0, Math.sin(2 * Math.PI * 2.5 * t))) + 0.01 * (rnd() * 2 - 1);
    peak = Math.max(peak, Math.abs(y[i]));
  }
  for (let i = 0; i < n; i++) y[i] = (0.8 * y[i]) / peak;
  return y;
}


function writeWav(path: string, chans: Float32Array[], sr: number = SR, float32: boolean = false): void {
  // WAV 저장: 16비트 PCM(기본) 또는 32비트 float. chans[채널][시간] -> 샘플이 채널마다 번갈아 들어감
  const ch = chans.length;
  const n = chans[0].length;
  const bytes = float32 ? 4 : 2;
  const buf = Buffer.alloc(44 + n * ch * bytes);
  buf.write("RIFF", 0, "ascii");
  buf.writeUInt32LE(36 + n * ch * bytes, 4);
  buf.write("WAVEfmt ", 8, "ascii");
  buf.writeUInt32LE(16, 16); // fmt 덩어리 크기
  buf.writeUInt16LE(float32 ? 3 : 1, 20); // 1 = PCM, 3 = float
  buf.writeUInt16LE(ch, 22); // 채널 수
  buf.writeUInt32LE(sr, 24);
  buf.writeUInt32LE(sr * ch * bytes, 28); // 1초 바이트 수
  buf.writeUInt16LE(ch * bytes, 32); // 시간 한 칸 바이트 수
  buf.writeUInt16LE(bytes * 8, 34); // 비트 깊이
  buf.write("data", 36, "ascii");
  buf.writeUInt32LE(n * ch * bytes, 40);
  for (let i = 0; i < n; i++) {
    for (let c = 0; c < ch; c++) {
      const v = Math.max(-1, Math.min(1, chans[c][i])); // -1~1 밖은 잘라 냄
      const at = 44 + (i * ch + c) * bytes;
      if (float32) buf.writeFloatLE(v, at);
      else buf.writeInt16LE(Math.round(v * 32767), at);
    }
  }
  writeFileSync(path, buf);
}

function readWav(path: string): { chans: Float32Array[]; sr: number; bits: number } {
  // 16비트 PCM · 32비트 float WAV 읽기 -> chans[채널][시간]
  const b = readFileSync(path);
  if (b.toString("ascii", 0, 4) !== "RIFF" || b.toString("ascii", 8, 12) !== "WAVE") throw new Error(`${path}: WAV 파일이 아니에요`);
  let fmt = 1;
  let ch = 1;
  let sr = 0;
  let bits = 16;
  for (let pos = 12; pos + 8 <= b.length; ) {
    const id = b.toString("ascii", pos, pos + 4);
    const size = b.readUInt32LE(pos + 4);
    const body = pos + 8;
    if (id === "fmt ") {
      fmt = b.readUInt16LE(body);
      ch = b.readUInt16LE(body + 2);
      sr = b.readUInt32LE(body + 4);
      bits = b.readUInt16LE(body + 14);
    } else if (id === "data") {
      const step = (bits / 8) * ch;
      const n = Math.floor(Math.min(size, b.length - body) / step);
      const chans = Array.from({ length: ch }, () => new Float32Array(n));
      for (let i = 0; i < n; i++) {
        for (let c = 0; c < ch; c++) {
          const at = body + i * step + c * (bits / 8);
          chans[c][i] = fmt === 3 ? b.readFloatLE(at) : b.readInt16LE(at) / 32768;
        }
      }
      return { chans, sr, bits };
    }
    pos = body + size + (size % 2); // 덩어리는 짝수 바이트로 맞춰 있음
  }
  throw new Error(`${path}: data 덩어리가 없어요`);
}


function resample(y: Float32Array, from: number, to: number): Float32Array {
  // 창 씌운 sinc 보간: 줄일 때는 새 나이퀴스트(to / 2) 위의 소리를 먼저 걸러 내서 겹침(aliasing)을 막는다
  const ratio = from / to;
  const cut = Math.min(1, to / from); // 줄일 때만 컷오프를 낮춤
  const w = 16 / cut; // 한쪽으로 보는 원본 샘플 수
  const out = new Float32Array(Math.floor(y.length / ratio));
  for (let i = 0; i < out.length; i++) {
    const x = i * ratio;
    let s = 0;
    for (let k = Math.max(0, Math.ceil(x - w)); k <= Math.min(y.length - 1, Math.floor(x + w)); k++) {
      const d = k - x;
      const a = d * cut;
      const sinc = a === 0 ? 1 : Math.sin(Math.PI * a) / (Math.PI * a);
      s += y[k] * cut * sinc * (0.5 + 0.5 * Math.cos((Math.PI * d) / w));
    }
    out[i] = s;
  }
  return out;
}


const rms = (x: ArrayLike<number>): number => Math.sqrt(Array.from(x).reduce((a, v) => a + v * v, 0) / x.length);

// 1) 소리 = 숫자 배열: 440 Hz 사인파의 RMS는 A / 루트2
const y = tone(440, 1);
console.log(`길이 ${y.length} · RMS ${rms(y).toFixed(4)} (이론 ${(0.5 / Math.sqrt(2)).toFixed(4)})`);
check(y.length === SR && Math.abs(rms(y) - 0.5 / Math.SQRT2) < 1e-3, "RMS = 진폭 / 루트2 입니다.");

// 2) 44.1kHz stereo 고음질 원본 만들기 (오른쪽은 작고 조금 늦게)
const v44 = synthVoice(2, 140, 0, 44100);
const right = new Float32Array(v44.length);
for (let i = 0; i < v44.length; i++) right[i] = 0.7 * v44[(i - 200 + v44.length) % v44.length];
writeWav("speech_hq.wav", [v44, right], 44100);
const hq = readWav("speech_hq.wav");
console.log(`원본 ${hq.sr} Hz · ${hq.chans.length}ch · ${(hq.chans[0].length / hq.sr).toFixed(2)}초 · ${(statSync("speech_hq.wav").size / 1024).toFixed(0)} KB`);

// 3) 샘플링 + 채널: 16kHz mono로 (두 채널 평균 → 나이퀴스트 위 걸러 내며 줄이기)
const mono = Float32Array.from(hq.chans[0], (v, i) => (v + hq.chans[1][i]) / 2);
const y16 = resample(mono, hq.sr, SR);
console.log(`16kHz mono: ${y16.length.toLocaleString()}개 (원본의 ${((y16.length / v44.length) * 100).toFixed(1)}%)`);
check(Math.abs(y16.length - 32000) <= 1, "2초 x 16,000 = 32,000개여야 해요.");

// 4) 양자화: 비트가 늘 때마다 SNR이 약 6 dB 좋아진다 (6.02 b + 1.76)
function quantize(x: Float32Array, bits: number): Float32Array {
  const half = 2 ** (bits - 1) - 1;
  return x.map((v) => Math.round(v * half) / half);
}
const x = tone(440, 1, SR, 0.999);
const snr = (b: number): number => 10 * Math.log10(rms(x) ** 2 / rms(quantize(x, b).map((v, i) => v - x[i])) ** 2);
for (const b of [4, 8, 16]) console.log(`${String(b).padStart(2)}bit: SNR ${snr(b).toFixed(1)} dB (이론 ${(6.02 * b + 1.76).toFixed(1)} dB)`);
check(Math.abs(snr(8) - (6.02 * 8 + 1.76)) < 3, "8bit SNR은 약 49.9 dB 입니다.");

// 5) 파일 크기: 16bit mono WAV = 초당 샘플 수 x 2바이트 x 채널 + 머리말 44바이트
writeWav("f.wav", [y16], SR);
const actual = statSync("f.wav").size;
const predict = y16.length * 2 * 1;
console.log(`예측 ${predict.toLocaleString()} 바이트 + 머리말 44 = ${(predict + 44).toLocaleString()} | 실제 ${actual.toLocaleString()} 바이트`);
check(actual - predict === 44, "WAV 크기 = 샘플 수 x 2바이트 + 44 입니다.");

// 6) 전처리기: 어떤 WAV든 16kHz mono 16bit WAV로 (앞뒤 묵음 자르고 가장 큰 소리를 0.9로)
function makeModelReady(src: string, dst: string): string {
  const w = readWav(src);
  const m = Float32Array.from(w.chans[0], (_, i) => w.chans.reduce((a, c) => a + c[i], 0) / w.chans.length);
  let r = resample(m, w.sr, SR);
  const loud = r.reduce((a, v) => Math.max(a, Math.abs(v)), 0);
  const thr = loud * 10 ** (-30 / 20);
  let s = 0;
  let e = r.length - 1;
  while (s < e && Math.abs(r[s]) < thr) s++;
  while (e > s && Math.abs(r[e]) < thr) e--;
  r = r.slice(s, e + 1);
  const peak = r.reduce((a, v) => Math.max(a, Math.abs(v)), 1e-9);
  writeWav(dst, [r.map((v) => (v / peak) * 0.9)], SR);
  return dst;
}
const ready = readWav(makeModelReady("speech_hq.wav", "ready.wav"));
console.log(`ready.wav: ${ready.sr} Hz · ${ready.chans.length}ch · ${ready.bits}bit · ${(ready.chans[0].length / ready.sr).toFixed(2)}초`);
check(ready.sr === 16000 && ready.chans.length === 1 && ready.bits === 16, "16kHz · mono · 16bit 이어야 해요.");

sound.typescript:
// D2 · Part 1 · 소리의 정체 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d02_sound.ts
//   주파수 · 진폭 · 주기 · dB · RMS를 숫자로 확인하고 880 Hz 소리를 FFT로 검사
import { writeFileSync } from "node:fs";
const SR = 16000; // 음성 모델 표준: 1초에 16,000번 측정 (16kHz)

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}


function tone(freq: number, sec: number = 1, sr: number = SR, amp: number = 0.5, phase: number = 0): Float32Array {
  // freq Hz 순수한 소리(사인파) x(t) = A sin(2 pi f t + phi)
  const y = new Float32Array(Math.floor(sr * sec));
  for (let i = 0; i < y.length; i++) y[i] = amp * Math.sin(2 * Math.PI * freq * (i / sr) + phase);
  return y;
}


function fft(re: Float64Array, im: Float64Array): void {
  // 제자리 FFT (쿨리-튜키, 길이는 2의 거듭제곱)
  const n = re.length;
  for (let i = 1, j = 0; i < n; i++) {
    let bit = n >> 1;
    for (; j & bit; bit >>= 1) j ^= bit;
    j ^= bit;
    if (i < j) {
      [re[i], re[j]] = [re[j], re[i]];
      [im[i], im[j]] = [im[j], im[i]];
    }
  }
  for (let len = 2; len <= n; len <<= 1) {
    const ang = (-2 * Math.PI) / len;
    for (let i = 0; i < n; i += len) {
      for (let k = 0; k < len / 2; k++) {
        const wr = Math.cos(ang * k);
        const wi = Math.sin(ang * k);
        const a = i + k;
        const b = a + len / 2;
        const xr = re[b] * wr - im[b] * wi;
        const xi = re[b] * wi + im[b] * wr;
        re[b] = re[a] - xr;
        im[b] = im[a] - xi;
        re[a] += xr;
        im[a] += xi;
      }
    }
  }
}

function hann(n: number): Float64Array {
  // Hann 창 (대칭형, np.hanning 과 같음): 0.5 - 0.5 cos(2 pi i / (n-1))
  return Float64Array.from({ length: n }, (_, i) => 0.5 - 0.5 * Math.cos((2 * Math.PI * i) / (n - 1)));
}

function magnitude(x: ArrayLike<number>, n: number, window?: ArrayLike<number>): Float64Array {
  // x 앞쪽 n개(창 곱하기, 모자라면 0으로 채움)의 FFT 크기 |X[k]|, k = 0 ~ n/2
  const re = new Float64Array(n);
  const im = new Float64Array(n);
  for (let i = 0; i < n && i < x.length; i++) re[i] = x[i] * (window ? window[i] : 1);
  fft(re, im);
  return Float64Array.from({ length: n / 2 + 1 }, (_, k) => Math.hypot(re[k], im[k]));
}

function peakHz(x: ArrayLike<number>, sr: number, n: number): number {
  // 가장 센 주파수(Hz): 가장 큰 FFT 칸 번호 k 와 칸 간격 sr / n 으로
  const m = magnitude(x, n, hann(n));
  let k = 1;
  for (let i = 1; i < m.length; i++) if (m[i] > m[k]) k = i;
  return (k * sr) / n;
}


const rms = (x: ArrayLike<number>): number => Math.sqrt(Array.from(x).reduce((a, v) => a + v * v, 0) / x.length);

// 숫자 배열의 정체: 220 Hz를 20ms만
const y = tone(220, 0.02);
console.log("길이:", y.length, "| 자료형: Float32Array");
console.log("처음 8개 숫자:", Array.from(y.slice(0, 8), (v) => v.toFixed(3)).join(", "));

// 주기 T = 1/f, 1주기당 샘플 수 = fs/f
for (const f of [220, 440, 880]) console.log(`${String(f).padStart(4)} Hz → 주기 ${(1000 / f).toFixed(3)} ms, 1주기당 샘플 ${(SR / f).toFixed(1)}개`);

// 같은 440 Hz, 진폭만 다르게: 20 log10(A1/A0) dB
for (const [a1, a0] of [[0.2, 0.05], [0.8, 0.2], [0.8, 0.05]]) console.log(`진폭 ${a1} vs ${a0}: ${(20 * Math.log10(a1 / a0)).toFixed(2)} dB`);

// RMS는 이론값 A / 루트2
const loud = tone(440, 1, SR, 0.8);
console.log(`RMS 측정 ${rms(loud).toFixed(4)} | 이론 ${(0.8 / Math.SQRT2).toFixed(4)}`);
check(Math.abs(rms(loud) - 0.8 / Math.SQRT2) < 1e-3, "RMS = A / 루트2 입니다.");

// 빈칸 실습 1의 답: 880 Hz 소리를 만들어 FFT로 주파수를 잰다 (FFT 길이는 2의 거듭제곱 → 앞 8192개)
const myTone = tone(880);
const hz = peakHz(myTone, SR, 8192);
console.log(`측정된 주파수: ${hz.toFixed(0)} Hz`);
writeFileSync("tone_880.txt", Array.from(myTone.slice(0, 16), (v) => v.toFixed(4)).join("\n"));
check(Math.abs(hz - 880) < 2.5, "tone() 안에 주파수 숫자 880을 넣으세요.");

sampling.typescript:
// D2 · Part 2 · 샘플링: 1초에 몇 번 측정할까 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d02_sampling.ts
//   건너뛰기(aliasing) vs 제대로 줄이기(resample): 접힌 주파수를 예측값과 비교하고 16kHz 변환 길이 확인
const SR = 16000; // 음성 모델 표준: 1초에 16,000번 측정 (16kHz)

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}


function fft(re: Float64Array, im: Float64Array): void {
  // 제자리 FFT (쿨리-튜키, 길이는 2의 거듭제곱)
  const n = re.length;
  for (let i = 1, j = 0; i < n; i++) {
    let bit = n >> 1;
    for (; j & bit; bit >>= 1) j ^= bit;
    j ^= bit;
    if (i < j) {
      [re[i], re[j]] = [re[j], re[i]];
      [im[i], im[j]] = [im[j], im[i]];
    }
  }
  for (let len = 2; len <= n; len <<= 1) {
    const ang = (-2 * Math.PI) / len;
    for (let i = 0; i < n; i += len) {
      for (let k = 0; k < len / 2; k++) {
        const wr = Math.cos(ang * k);
        const wi = Math.sin(ang * k);
        const a = i + k;
        const b = a + len / 2;
        const xr = re[b] * wr - im[b] * wi;
        const xi = re[b] * wi + im[b] * wr;
        re[b] = re[a] - xr;
        im[b] = im[a] - xi;
        re[a] += xr;
        im[a] += xi;
      }
    }
  }
}

function hann(n: number): Float64Array {
  // Hann 창 (대칭형, np.hanning 과 같음): 0.5 - 0.5 cos(2 pi i / (n-1))
  return Float64Array.from({ length: n }, (_, i) => 0.5 - 0.5 * Math.cos((2 * Math.PI * i) / (n - 1)));
}

function magnitude(x: ArrayLike<number>, n: number, window?: ArrayLike<number>): Float64Array {
  // x 앞쪽 n개(창 곱하기, 모자라면 0으로 채움)의 FFT 크기 |X[k]|, k = 0 ~ n/2
  const re = new Float64Array(n);
  const im = new Float64Array(n);
  for (let i = 0; i < n && i < x.length; i++) re[i] = x[i] * (window ? window[i] : 1);
  fft(re, im);
  return Float64Array.from({ length: n / 2 + 1 }, (_, k) => Math.hypot(re[k], im[k]));
}

function peakHz(x: ArrayLike<number>, sr: number, n: number): number {
  // 가장 센 주파수(Hz): 가장 큰 FFT 칸 번호 k 와 칸 간격 sr / n 으로
  const m = magnitude(x, n, hann(n));
  let k = 1;
  for (let i = 1; i < m.length; i++) if (m[i] > m[k]) k = i;
  return (k * sr) / n;
}


function resample(y: Float32Array, from: number, to: number): Float32Array {
  // 창 씌운 sinc 보간: 줄일 때는 새 나이퀴스트(to / 2) 위의 소리를 먼저 걸러 내서 겹침(aliasing)을 막는다
  const ratio = from / to;
  const cut = Math.min(1, to / from); // 줄일 때만 컷오프를 낮춤
  const w = 16 / cut; // 한쪽으로 보는 원본 샘플 수
  const out = new Float32Array(Math.floor(y.length / ratio));
  for (let i = 0; i < out.length; i++) {
    const x = i * ratio;
    let s = 0;
    for (let k = Math.max(0, Math.ceil(x - w)); k <= Math.min(y.length - 1, Math.floor(x + w)); k++) {
      const d = k - x;
      const a = d * cut;
      const sinc = a === 0 ? 1 : Math.sin(Math.PI * a) / (Math.PI * a);
      s += y[k] * cut * sinc * (0.5 + 0.5 * Math.cos((Math.PI * d) / w));
    }
    out[i] = s;
  }
  return out;
}


const aliasFreq = (f: number, fs: number): number => Math.abs(f - Math.round(f / fs) * fs);
const rms = (x: ArrayLike<number>): number => Math.sqrt(Array.from(x).reduce((a, v) => a + v * v, 0) / x.length);

const fsOld = 44100;
const fsNew = 11025;
console.log(`새 나이퀴스트 주파수 = ${fsNew / 2} Hz`);
console.log("원래 f   예측  건너뛰기  resample 후 세기");
let ok = true;
for (const f of [1000, 3000, 5000, 7000, 9000]) {
  const y = Float32Array.from({ length: fsOld }, (_, i) => Math.sin((2 * Math.PI * f * i) / fsOld));
  const skip = y.filter((_, i) => i % 4 === 0); // 4개 중 1개만 남김
  const skipF = peakHz(skip, fsNew, 8192);
  const res = resample(y, fsOld, fsNew).slice(200, -200);
  const keepDb = 20 * Math.log10(rms(res) / rms(y) + 1e-12);
  const pred = f < fsNew / 2 ? f : aliasFreq(f, fsNew);
  ok = ok && Math.abs(skipF - pred) < 3;
  if (f > fsNew / 2) ok = ok && keepDb < -30; // 제대로 줄이면 접힌 소리는 사라짐
  console.log(`${String(f).padStart(6)} ${pred.toFixed(0).padStart(6)} ${skipF.toFixed(0).padStart(8)} ${keepDb.toFixed(1).padStart(12)} dB ${f > fsNew / 2 ? "(접힘)" : ""}`);
}
check(ok, "건너뛰기는 예측한 주파수로 접히고, resample은 나이퀴스트 위를 지워야 해요.");

// 빈칸 실습 2의 답: 44.1kHz 원본을 음성 모델 표준 16kHz로
const chirp = new Float32Array(3 * 44100);
let phase = 0;
for (let i = 0; i < chirp.length; i++) {
  phase += (2 * Math.PI * 200 * (7000 / 200) ** (i / chirp.length)) / 44100; // 200 → 7,000 Hz로 기하급수적으로 올라감
  chirp[i] = 0.5 * Math.sin(phase);
}
const y16 = resample(chirp, 44100, 16000);
console.log(`샘플 ${chirp.length.toLocaleString()}개 → ${y16.length.toLocaleString()}개 (예측 ${Math.floor((chirp.length * 16000) / 44100)})`);
check(Math.abs(y16.length / chirp.length - 16000 / 44100) < 0.001, "target 16000 이어야 해요.");

quant.typescript:
// D2 · Part 3 · 양자화: 소리의 크기를 몇 단계로 적을까 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d02_quant.ts
//   비트 깊이별 단계 수 · 양자화 잡음 SNR(6.02 b + 1.76 dB)을 재고 16bit PCM으로 저장
import { readFileSync, statSync, writeFileSync } from "node:fs";
const SR = 16000; // 음성 모델 표준: 1초에 16,000번 측정 (16kHz)

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}


function tone(freq: number, sec: number = 1, sr: number = SR, amp: number = 0.5, phase: number = 0): Float32Array {
  // freq Hz 순수한 소리(사인파) x(t) = A sin(2 pi f t + phi)
  const y = new Float32Array(Math.floor(sr * sec));
  for (let i = 0; i < y.length; i++) y[i] = amp * Math.sin(2 * Math.PI * freq * (i / sr) + phase);
  return y;
}


function writeWav(path: string, chans: Float32Array[], sr: number = SR, float32: boolean = false): void {
  // WAV 저장: 16비트 PCM(기본) 또는 32비트 float. chans[채널][시간] -> 샘플이 채널마다 번갈아 들어감
  const ch = chans.length;
  const n = chans[0].length;
  const bytes = float32 ? 4 : 2;
  const buf = Buffer.alloc(44 + n * ch * bytes);
  buf.write("RIFF", 0, "ascii");
  buf.writeUInt32LE(36 + n * ch * bytes, 4);
  buf.write("WAVEfmt ", 8, "ascii");
  buf.writeUInt32LE(16, 16); // fmt 덩어리 크기
  buf.writeUInt16LE(float32 ? 3 : 1, 20); // 1 = PCM, 3 = float
  buf.writeUInt16LE(ch, 22); // 채널 수
  buf.writeUInt32LE(sr, 24);
  buf.writeUInt32LE(sr * ch * bytes, 28); // 1초 바이트 수
  buf.writeUInt16LE(ch * bytes, 32); // 시간 한 칸 바이트 수
  buf.writeUInt16LE(bytes * 8, 34); // 비트 깊이
  buf.write("data", 36, "ascii");
  buf.writeUInt32LE(n * ch * bytes, 40);
  for (let i = 0; i < n; i++) {
    for (let c = 0; c < ch; c++) {
      const v = Math.max(-1, Math.min(1, chans[c][i])); // -1~1 밖은 잘라 냄
      const at = 44 + (i * ch + c) * bytes;
      if (float32) buf.writeFloatLE(v, at);
      else buf.writeInt16LE(Math.round(v * 32767), at);
    }
  }
  writeFileSync(path, buf);
}

function readWav(path: string): { chans: Float32Array[]; sr: number; bits: number } {
  // 16비트 PCM · 32비트 float WAV 읽기 -> chans[채널][시간]
  const b = readFileSync(path);
  if (b.toString("ascii", 0, 4) !== "RIFF" || b.toString("ascii", 8, 12) !== "WAVE") throw new Error(`${path}: WAV 파일이 아니에요`);
  let fmt = 1;
  let ch = 1;
  let sr = 0;
  let bits = 16;
  for (let pos = 12; pos + 8 <= b.length; ) {
    const id = b.toString("ascii", pos, pos + 4);
    const size = b.readUInt32LE(pos + 4);
    const body = pos + 8;
    if (id === "fmt ") {
      fmt = b.readUInt16LE(body);
      ch = b.readUInt16LE(body + 2);
      sr = b.readUInt32LE(body + 4);
      bits = b.readUInt16LE(body + 14);
    } else if (id === "data") {
      const step = (bits / 8) * ch;
      const n = Math.floor(Math.min(size, b.length - body) / step);
      const chans = Array.from({ length: ch }, () => new Float32Array(n));
      for (let i = 0; i < n; i++) {
        for (let c = 0; c < ch; c++) {
          const at = body + i * step + c * (bits / 8);
          chans[c][i] = fmt === 3 ? b.readFloatLE(at) : b.readInt16LE(at) / 32768;
        }
      }
      return { chans, sr, bits };
    }
    pos = body + size + (size % 2); // 덩어리는 짝수 바이트로 맞춰 있음
  }
  throw new Error(`${path}: data 덩어리가 없어요`);
}


function quantize(y: Float32Array, bits: number): Float32Array {
  // -1 ~ 1 사이의 소리를 bits 비트(2**bits 단계)로 거칠게 만든다
  const half = 2 ** (bits - 1) - 1;
  return y.map((v) => Math.round(v * half) / half);
}
const power = (x: ArrayLike<number>): number => Array.from(x).reduce((a, v) => a + v * v, 0) / x.length;

// 비트별 SNR 측정 vs 이론 6.02 b + 1.76 (꽉 찬 사인파 기준)
const x = tone(440, 1, SR, 0.999);
console.log(" bits  단계 2^b  측정 SNR  이론 SNR");
let worst = 0;
for (const b of [2, 4, 8, 12, 16]) {
  const noise = quantize(x, b).map((v, i) => v - x[i]);
  const snr = 10 * Math.log10(power(x) / power(noise));
  if (b >= 4) worst = Math.max(worst, Math.abs(snr - (6.02 * b + 1.76))); // 2bit는 너무 거칠어서 공식이 안 맞음
  console.log(`${String(b).padStart(5)} ${(2 ** b).toLocaleString().padStart(9)} ${snr.toFixed(1).padStart(8)}dB ${(6.02 * b + 1.76).toFixed(1).padStart(8)}dB`);
}
check(worst < 3, "4bit 이상은 측정 SNR이 6.02 b + 1.76 dB 근처여야 해요.");

// 저장할 때 비트 깊이: 16비트 PCM(샘플당 2바이트) vs 32비트 float(4바이트)
const y = tone(220, 1, SR, 0.5);
writeWav("q_pcm16.wav", [y], SR);
writeWav("q_float.wav", [y], SR, true);
for (const f of ["q_pcm16.wav", "q_float.wav"]) {
  const w = readWav(f);
  console.log(`${f.padEnd(12)} ${w.bits}bit ${(statSync(f).size / 1024).toFixed(1).padStart(6)} KB`);
}

// 빈칸 실습 3의 답: 16bit로 저장하고 다시 읽어 보기 (16bit로 줄인 오차는 1/32767 안쪽)
const back = readWav("q_pcm16.wav");
const err = Math.max(...back.chans[0].map((v, i) => Math.abs(v - y[i])));
console.log(`16bit 저장 후 최대 오차 ${err.toExponential(2)} (한 단계 = ${(1 / 32767).toExponential(2)})`);
check(back.bits === 16 && err <= 1 / 32767 && readFileSync("q_pcm16.wav").length === 44 + 2 * y.length, "16bit PCM은 샘플당 2바이트입니다.");

