  writeFileSync(path, buf);
}

function readWav(path: string): { chans: Float32Array[]; sr: number; bits: number } {
  // 16비트 PCM · 32비트 float WAV 읽기 -> chans[채널][시간]
  const b = readFileSync(path);
  if (b.toString("ascii", 0, 4) !== "RIFF" || b.toString("ascii", 8, 12) !== "WAVE") throw new Error(`${path}: WAV 파일이 아니에요`);
  let fmt = 1;
  let ch = 1;
  let sr = 0;
  let bits = 16;
  for (let pos = 12; pos + 8 <= b.length; ) {
    const id = b.toString("ascii", pos, pos + 4);
    const size = b.readUInt32LE(pos + 4);
    const body = pos + 8;
    if (id === "fmt ") {
      fmt = b.readUInt16LE(body);
      ch = b.readUInt16LE(body + 2);
      sr = b.readUInt32LE(body + 4);
      bits = b.readUInt16LE(body + 14);
    } else if (id === "data") {
      const step = (bits / 8) * ch;
      const n = Math.floor(Math.min(size, b.length - body) / step);
      const chans = Array.from({ length: ch }, () => new Float32Array(n));
      for (let i = 0; i < n; i++) {
        for (let c = 0; c < ch; c++) {
          const at = body + i * step + c * (bits / 8);
          chans[c][i] = fmt === 3 ? b.readFloatLE(at) : b.readInt16LE(at) / 32768;
        }
      }
      return { chans, sr, bits };
    }
    pos = body + size + (size % 2); // 덩어리는 짝수 바이트로 맞춰 있음
  }
  throw new Error(`${path}: data 덩어리가 없어요`);
}


const y = synthVoice(3);
const T = y.length / SR;
writeWav("f.wav", [y], SR);
const wav = readFileSync("f.wav");

// 무손실: deflate(zip과 같은 방식)로 줄였다 풀면 바이트가 완전히 같다 (FLAC 같은 성격)
const packed = deflateSync(wav);
const unpacked = inflateSync(packed);
const lossless = Buffer.compare(wav, unpacked) === 0;

// 손실: 8비트 mu-law(전화 방식) — 크기는 절반, 대신 숫자가 조금 바뀐다 (MP3 · Opus 같은 성격)
const MU = 255;
const enc = Uint8Array.from(y, (v) => Math.round(((Math.sign(v) * Math.log1p(MU * Math.abs(v))) / Math.log1p(MU) + 1) * 127.5));
const dec = Float32Array.from(enc, (c) => {
  const u = c / 127.5 - 1;
  return (Math.sign(u) * ((1 + MU) ** Math.abs(u) - 1)) / MU;
});
const diff = Math.max(...dec.map((v, i) => Math.abs(v - y[i])));

const kb = (n: number): string => (n / 1024).toFixed(1).padStart(6);
console.log("파일          크기(KB)  WAV 대비  원래 숫자와의 차이");
console.log(`WAV           ${kb(wav.length)}     100%   0 (기준)`);
console.log(`deflate       ${kb(packed.length)}  ${((packed.length / wav.length) * 100).toFixed(0).padStart(6)}%   0 (완전히 같음)`);
console.log(`8bit mu-law   ${kb(enc.length)}  ${((enc.length / wav.length) * 100).toFixed(0).padStart(6)}%   ${diff.toFixed(4)}`);

// 비트레이트 공식: 크기 = R x T / 8, PCM의 R = fs x 비트 x 채널
const R = SR * 16 * 1;
console.log(`R_PCM = ${SR} x 16 x 1 = ${R / 1000} kbps, 길이 ${T.toFixed(2)}초 → 예측 ${((R * T) / 8 / 1024).toFixed(1)} KB (실제 ${(wav.length / 1024).toFixed(1)} KB, 머리말 44바이트 차이)`);
check(lossless && packed.length < wav.length, "무손실은 풀면 바이트가 같고 크기는 더 작아요.");
check(wav.length - (R * T) / 8 === 44, "크기 = R x T / 8 (+ 머리말 44바이트) 입니다.");
check(enc.length < wav.length && diff > 0, "손실은 더 작지만 숫자가 조금씩 바뀌어요.");

