// D2 · Part 6 · 오디오 다루는 도구들 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d02_libs.ts
//   같은 WAV를 Buffer · DataView · 타입 배열 세 방법으로 읽어 같은 숫자인지, 정수 / 32768 = 실수인지 확인
import { readFileSync, writeFileSync } from "node:fs";
const SR = 16000; // 음성 모델 표준: 1초에 16,000번 측정 (16kHz)

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}


function tone(freq: number, sec: number = 1, sr: number = SR, amp: number = 0.5, phase: number = 0): Float32Array {
  // freq Hz 순수한 소리(사인파) x(t) = A sin(2 pi f t + phi)
  const y = new Float32Array(Math.floor(sr * sec));
  for (let i = 0; i < y.length; i++) y[i] = amp * Math.sin(2 * Math.PI * freq * (i / sr) + phase);
  return y;
}


function writeWav(path: string, chans: Float32Array[], sr: number = SR, float32: boolean = false): void {
  // WAV 저장: 16비트 PCM(기본) 또는 32비트 float. chans[채널][시간] -> 샘플이 채널마다 번갈아 들어감
  const ch = chans.length;
  const n = chans[0].length;
  const bytes = float32 ? 4 : 2;
  const buf = Buffer.alloc(44 + n * ch * bytes);
  buf.write("RIFF", 0, "ascii");
  buf.writeUInt32LE(36 + n * ch * bytes, 4);
  buf.write("WAVEfmt ", 8, "ascii");
  buf.writeUInt32LE(16, 16); // fmt 덩어리 크기
  buf.writeUInt16LE(float32 ? 3 : 1, 20); // 1 = PCM, 3 = float
  buf.writeUInt16LE(ch, 22); // 채널 수
  buf.writeUInt32LE(sr, 24);
  buf.writeUInt32LE(sr * ch * bytes, 28); // 1초 바이트 수
  buf.writeUInt16LE(ch * bytes, 32); // 시간 한 칸 바이트 수
  buf.writeUInt16LE(bytes * 8, 34); // 비트 깊이
  buf.write("data", 36, "ascii");
  buf.writeUInt32LE(n * ch * bytes, 40);
  for (let i = 0; i < n; i++) {
    for (let c = 0; c < ch; c++) {
      const v = Math.max(-1, Math.min(1, chans[c][i])); // -1~1 밖은 잘라 냄
      const at = 44 + (i * ch + c) * bytes;
      if (float32) buf.writeFloatLE(v, at);
      else buf.writeInt16LE(Math.round(v * 32767), at);
    }
  }
  writeFileSync(path, buf);
}

function readWav(path: string): { chans: Float32Array[]; sr: number; bits: number } {
  // 16비트 PCM · 32비트 float WAV 읽기 -> chans[채널][시간]
  const b = readFileSync(path);
  if (b.toString("ascii", 0, 4) !== "RIFF" || b.toString("ascii", 8, 12) !== "WAVE") throw new Error(`${path}: WAV 파일이 아니에요`);
  let fmt = 1;
  let ch = 1;
  let sr = 0;
  let bits = 16;
  for (let pos = 12; pos + 8 <= b.length; ) {
    const id = b.toString("ascii", pos, pos + 4);
    const size = b.readUInt32LE(pos + 4);
    const body = pos + 8;
    if (id === "fmt ") {
      fmt = b.readUInt16LE(body);
      ch = b.readUInt16LE(body + 2);
      sr = b.readUInt32LE(body + 4);
      bits = b.readUInt16LE(body + 14);
    } else if (id === "data") {
      const step = (bits / 8) * ch;
      const n = Math.floor(Math.min(size, b.length - body) / step);
      const chans = Array.from({ length: ch }, () => new Float32Array(n));
      for (let i = 0; i < n; i++) {
        for (let c = 0; c < ch; c++) {
          const at = body + i * step + c * (bits / 8);
          chans[c][i] = fmt === 3 ? b.readFloatLE(at) : b.readInt16LE(at) / 32768;
        }
      }
      return { chans, sr, bits };
    }
    pos = body + size + (size % 2); // 덩어리는 짝수 바이트로 맞춰 있음
  }
  throw new Error(`${path}: data 덩어리가 없어요`);
}


// 44.1kHz stereo 16bit WAV 하나를 만든다 (왼쪽 440 Hz, 오른쪽 660 Hz)
const sr0 = 44100;
writeWav("both.wav", [tone(440, 1, sr0), tone(660, 1, sr0)], sr0);
const buf = readFileSync("both.wav");
const n = (buf.length - 44) / 4; // 시간 칸 수 (한 칸 = 2채널 x 2바이트)

// 1) Buffer: 읽는 위치와 크기를 내가 정해서 읽기
const viaBuffer = Int16Array.from({ length: n * 2 }, (_, i) => buf.readInt16LE(44 + i * 2));
// 2) DataView: 같은 일을 엔디안(바이트 순서)을 적어 가며
const dv = new DataView(buf.buffer, buf.byteOffset, buf.byteLength);
const viaView = Int16Array.from({ length: n * 2 }, (_, i) => dv.getInt16(44 + i * 2, true));
// 3) 타입 배열: 메모리를 그대로 16비트 정수로 보기 (바이트 정렬이 맞아야 해서 복사해서)
const copy = buf.buffer.slice(buf.byteOffset + 44, buf.byteOffset + buf.length);
const viaTyped = new Int16Array(copy);
console.log(`Buffer ${viaBuffer.length}개 · DataView ${viaView.length}개 · 타입 배열 ${viaTyped.length}개 (시간 ${n}칸 x 2채널)`);
console.log(`헤더: ${buf.readUInt32LE(24)} Hz · ${buf.readUInt16LE(22)}ch · ${buf.readUInt16LE(34)}bit`);

const same = viaBuffer.every((v, i) => v === viaView[i] && v === viaTyped[i]);
check(same && viaBuffer.length === n * 2, "세 방법은 같은 숫자를 읽어야 해요.");

// 정수를 -1 ~ 1 실수로: / 32768 (readWav가 하는 일)
const w = readWav("both.wav");
check(w.sr === sr0 && w.chans.length === 2 && Math.abs(w.chans[0][10] - viaBuffer[20] / 32768) < 1e-9, "정수 / 32768 = 실수 값이어야 해요.");

editor.typescript:
// D2 · Part 6 · pydub 편집기 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d02_editor.ts
//   pydub 같은 AudioSegment로 자르기 · +6dB · 페이드 · 이어 붙이기 · 거꾸로, 길이와 배율 확인
import { readFileSync, writeFileSync } from "node:fs";
const SR = 16000; // 음성 모델 표준: 1초에 16,000번 측정 (16kHz)

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}


function synthVoice(seconds: number = 2, f0: number = 140, seed: number = 0, sr: number = SR): Float32Array {
  // 말소리 비슷한 합성 신호(mono): 기본음 + 배음 5개 + 음절 모양 세기 + 약한 잡음
  const n = Math.floor(seconds * sr);
  const y = new Float32Array(n);
  const rnd = mulberry32(seed);
  let phase = 0;
  let peak = 1e-9;
  for (let i = 0; i < n; i++) {
    const t = i / sr;
    phase += (2 * Math.PI * f0 * (1 + 0.05 * Math.sin(2 * Math.PI * 0.7 * t))) / sr;
    let v = 0;
    for (let k = 1; k <= 5; k++) v += Math.sin(k * phase) / k;
    y[i] = v * Math.sqrt(Math.max(0, Math.sin(2 * Math.PI * 2.5 * t))) + 0.01 * (rnd() * 2 - 1);
    peak = Math.max(peak, Math.abs(y[i]));
  }
  for (let i = 0; i < n; i++) y[i] = (0.8 * y[i]) / peak;
  return y;
}


function mulberry32(seed: number): () => number {
  // 씨앗(seed)이 같으면 늘 같은 난수 순서 (0 이상 1 미만)
  let a = seed >>> 0;
  return (): number => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function gauss(rnd: () => number): number {
  // 표준 정규분포 난수 (Box-Muller)
  return Math.sqrt(-2 * Math.log(rnd() + 1e-12)) * Math.cos(2 * Math.PI * rnd());
}


function writeWav(path: string, chans: Float32Array[], sr: number = SR, float32: boolean = false): void {
  // WAV 저장: 16비트 PCM(기본) 또는 32비트 float. chans[채널][시간] -> 샘플이 채널마다 번갈아 들어감
  const ch = chans.length;
  const n = chans[0].length;
  const bytes = float32 ? 4 : 2;
  const buf = Buffer.alloc(44 + n * ch * bytes);
  buf.write("RIFF", 0, "ascii");
  buf.writeUInt32LE(36 + n * ch * bytes, 4);
  buf.write("WAVEfmt ", 8, "ascii");
  buf.writeUInt32LE(16, 16); // fmt 덩어리 크기
  buf.writeUInt16LE(float32 ? 3 : 1, 20); // 1 = PCM, 3 = float
  buf.writeUInt16LE(ch, 22); // 채널 수
  buf.writeUInt32LE(sr, 24);
  buf.writeUInt32LE(sr * ch * bytes, 28); // 1초 바이트 수
  buf.writeUInt16LE(ch * bytes, 32); // 시간 한 칸 바이트 수
  buf.writeUInt16LE(bytes * 8, 34); // 비트 깊이
  buf.write("data", 36, "ascii");
  buf.writeUInt32LE(n * ch * bytes, 40);
  for (let i = 0; i < n; i++) {
    for (let c = 0; c < ch; c++) {
      const v = Math.max(-1, Math.min(1, chans[c][i])); // -1~1 밖은 잘라 냄
      const at = 44 + (i * ch + c) * bytes;
      if (float32) buf.writeFloatLE(v, at);
      else buf.writeInt16LE(Math.round(v * 32767), at);
    }
  }
  writeFileSync(path, buf);
}

function readWav(path: string): { chans: Float32Array[]; sr: number; bits: number } {
  // 16비트 PCM · 32비트 float WAV 읽기 -> chans[채널][시간]
  const b = readFileSync(path);
  if (b.toString("ascii", 0, 4) !== "RIFF" || b.toString("ascii", 8, 12) !== "WAVE") throw new Error(`${path}: WAV 파일이 아니에요`);
  let fmt = 1;
  let ch = 1;
  let sr = 0;
  let bits = 16;
  for (let pos = 12; pos + 8 <= b.length; ) {
    const id = b.toString("ascii", pos, pos + 4);
    const size = b.readUInt32LE(pos + 4);
    const body = pos + 8;
    if (id === "fmt ") {
      fmt = b.readUInt16LE(body);
      ch = b.readUInt16LE(body + 2);
      sr = b.readUInt32LE(body + 4);
      bits = b.readUInt16LE(body + 14);
    } else if (id === "data") {
      const step = (bits / 8) * ch;
      const n = Math.floor(Math.min(size, b.length - body) / step);
      const chans = Array.from({ length: ch }, () => new Float32Array(n));
      for (let i = 0; i < n; i++) {
        for (let c = 0; c < ch; c++) {
          const at = body + i * step + c * (bits / 8);
          chans[c][i] = fmt === 3 ? b.readFloatLE(at) : b.readInt16LE(at) / 32768;
        }
      }
      return { chans, sr, bits };
    }
    pos = body + size + (size % 2); // 덩어리는 짝수 바이트로 맞춰 있음
  }
  throw new Error(`${path}: data 덩어리가 없어요`);
}


class Segment {
  // pydub의 AudioSegment 흉내: 소리 배열 + 샘플링 레이트, 시간 단위는 ms
  y: Float32Array;
  sr: number;
  constructor(y: Float32Array, sr: number) {
    this.y = y;
    this.sr = sr;
  }
  get length(): number {
    return Math.round((this.y.length / this.sr) * 1000); // ms
  }
  slice(from: number, to: number = this.length): Segment {
    return new Segment(this.y.slice(Math.round((from * this.sr) / 1000), Math.round((to * this.sr) / 1000)), this.sr);
  }
  gain(db: number): Segment {
    const g = 10 ** (db / 20); // 20 log10 이득 → 곱하는 배율
    return new Segment(this.y.map((v) => v * g), this.sr);
  }
  fade(inMs: number, outMs: number): Segment {
    const out = this.y.slice();
    const a = Math.round((inMs * this.sr) / 1000);
    const b = Math.round((outMs * this.sr) / 1000);
    for (let i = 0; i < a; i++) out[i] *= i / a;
    for (let i = 0; i < b; i++) out[out.length - 1 - i] *= i / b;
    return new Segment(out, this.sr);
  }
  concat(o: Segment): Segment {
    const out = new Float32Array(this.y.length + o.y.length);
    out.set(this.y, 0);
    out.set(o.y, this.y.length);
    return new Segment(out, this.sr);
  }
  reverse(): Segment {
    return new Segment(this.y.slice().reverse(), this.sr);
  }
  static silent(ms: number, sr: number): Segment {
    return new Segment(new Float32Array(Math.round((ms * sr) / 1000)), sr);
  }
}

writeWav("speech.wav", [synthVoice(5)], SR);
const audio = new Segment(readWav("speech.wav").chans[0], SR);
console.log(`길이 ${audio.length} ms | ${audio.sr} Hz`);

const clip = audio.slice(1000, 4000); // 1초 ~ 4초 자르기
const loud = clip.gain(6); // 6dB 키우기 (약 2배)
const faded = clip.fade(500, 1000); // 0.5초 페이드 인, 1초 페이드 아웃
const both = clip.concat(Segment.silent(800, SR)).concat(clip.reverse()); // 이어 붙이기 (중간 0.8초 쉼)
for (const [name, seg] of [["자르기", clip], ["+6dB", loud], ["페이드", faded], ["이어 붙이기", both]] as Array<[string, Segment]>) {
  writeWav(`edit_${name === "+6dB" ? "gain" : name === "자르기" ? "clip" : name === "페이드" ? "fade" : "both"}.wav`, [seg.y], SR);
  console.log(`${name.padEnd(6)} → ${seg.length} ms`);
}

// 수식 검증: +6 dB는 약 2배 (10^(6/20) = 1.995)
const maxAbs = (x: Float32Array): number => x.reduce((a, v) => Math.max(a, Math.abs(v)), 0);
const ratio = maxAbs(loud.y) / maxAbs(clip.y);
console.log(`측정 배율 = ${ratio.toFixed(3)} | 이론 10^(6/20) = ${(10 ** (6 / 20)).toFixed(3)}`);
check(Math.abs(ratio - 10 ** (6 / 20)) < 0.02, "+6 dB는 약 1.995배입니다.");
check(both.length === 3000 + 800 + 3000, "이어 붙인 길이 = 3000 + 800 + 3000 ms 입니다.");

// 빈칸 실습 6의 답: 처음 2초 (밀리초 단위)
const first2 = audio.slice(0, 2000);
writeFileSync("first2.txt", String(first2.length));
check(first2.length === 2000 && faded.length === 3000 && faded.y[0] === 0, "2초 = 2000 ms, 페이드 인은 0에서 시작해요.");

