    let v = 0;
    for (let k = 1; k <= 5; k++) v += Math.sin(k * phase) / k;
    y[i] = v * Math.sqrt(Math.max(0, Math.sin(2 * Math.PI * 2.5 * t))) + 0.01 * (rnd() * 2 - 1);
    peak = Math.max(peak, Math.abs(y[i]));
  }
  for (let i = 0; i < n; i++) y[i] = (0.8 * y[i]) / peak;
  return y;
}


function mulberry32(seed: number): () => number {
  // 씨앗(seed)이 같으면 늘 같은 난수 순서 (0 이상 1 미만)
  let a = seed >>> 0;
  return (): number => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function gauss(rnd: () => number): number {
  // 표준 정규분포 난수 (Box-Muller)
  return Math.sqrt(-2 * Math.log(rnd() + 1e-12)) * Math.cos(2 * Math.PI * rnd());
}


function writeWav(path: string, chans: Float32Array[], sr: number = SR, float32: boolean = false): void {
  // WAV 저장: 16비트 PCM(기본) 또는 32비트 float. chans[채널][시간] -> 샘플이 채널마다 번갈아 들어감
  const ch = chans.length;
  const n = chans[0].length;
  const bytes = float32 ? 4 : 2;
  const buf = Buffer.alloc(44 + n * ch * bytes);
  buf.write("RIFF", 0, "ascii");
  buf.writeUInt32LE(36 + n * ch * bytes, 4);
  buf.write("WAVEfmt ", 8, "ascii");
  buf.writeUInt32LE(16, 16); // fmt 덩어리 크기
  buf.writeUInt16LE(float32 ? 3 : 1, 20); // 1 = PCM, 3 = float
  buf.writeUInt16LE(ch, 22); // 채널 수
  buf.writeUInt32LE(sr, 24);
  buf.writeUInt32LE(sr * ch * bytes, 28); // 1초 바이트 수
  buf.writeUInt16LE(ch * bytes, 32); // 시간 한 칸 바이트 수
  buf.writeUInt16LE(bytes * 8, 34); // 비트 깊이
  buf.write("data", 36, "ascii");
  buf.writeUInt32LE(n * ch * bytes, 40);
  for (let i = 0; i < n; i++) {
    for (let c = 0; c < ch; c++) {
      const v = Math.max(-1, Math.min(1, chans[c][i])); // -1~1 밖은 잘라 냄
      const at = 44 + (i * ch + c) * bytes;
      if (float32) buf.writeFloatLE(v, at);
      else buf.writeInt16LE(Math.round(v * 32767), at);
    }
  }
  writeFileSync(path, buf);
}

function readWav(path: string): { chans: Float32Array[]; sr: number; bits: number } {
  // 16비트 PCM · 32비트 float WAV 읽기 -> chans[채널][시간]
  const b = readFileSync(path);
  if (b.toString("ascii", 0, 4) !== "RIFF" || b.toString("ascii", 8, 12) !== "WAVE") throw new Error(`${path}: WAV 파일이 아니에요`);
  let fmt = 1;
  let ch = 1;
  let sr = 0;
  let bits = 16;
  for (let pos = 12; pos + 8 <= b.length; ) {
    const id = b.toString("ascii", pos, pos + 4);
    const size = b.readUInt32LE(pos + 4);
    const body = pos + 8;
    if (id === "fmt ") {
      fmt = b.readUInt16LE(body);
      ch = b.readUInt16LE(body + 2);
      sr = b.readUInt32LE(body + 4);
      bits = b.readUInt16LE(body + 14);
    } else if (id === "data") {
      const step = (bits / 8) * ch;
      const n = Math.floor(Math.min(size, b.length - body) / step);
      const chans = Array.from({ length: ch }, () => new Float32Array(n));
      for (let i = 0; i < n; i++) {
        for (let c = 0; c < ch; c++) {
          const at = body + i * step + c * (bits / 8);
          chans[c][i] = fmt === 3 ? b.readFloatLE(at) : b.readInt16LE(at) / 32768;
        }
      }
      return { chans, sr, bits };
    }
    pos = body + size + (size % 2); // 덩어리는 짝수 바이트로 맞춰 있음
  }
  throw new Error(`${path}: data 덩어리가 없어요`);
}


function resample(y: Float32Array, from: number, to: number): Float32Array {
  // 창 씌운 sinc 보간: 줄일 때는 새 나이퀴스트(to / 2) 위의 소리를 먼저 걸러 내서 겹침(aliasing)을 막는다
  const ratio = from / to;
  const cut = Math.min(1, to / from); // 줄일 때만 컷오프를 낮춤
  const w = 16 / cut; // 한쪽으로 보는 원본 샘플 수
  const out = new Float32Array(Math.floor(y.length / ratio));
  for (let i = 0; i < out.length; i++) {
    const x = i * ratio;
    let s = 0;
    for (let k = Math.max(0, Math.ceil(x - w)); k <= Math.min(y.length - 1, Math.floor(x + w)); k++) {
      const d = k - x;
      const a = d * cut;
      const sinc = a === 0 ? 1 : Math.sin(Math.PI * a) / (Math.PI * a);
      s += y[k] * cut * sinc * (0.5 + 0.5 * Math.cos((Math.PI * d) / w));
    }
    out[i] = s;
  }
  return out;
}


function makeModelReady(src: string, dst: string): string {
  // 어떤 WAV든 16kHz mono 16bit WAV로: 채널 평균 → resample → 묵음 자르기 → 볼륨 맞추기
  const w = readWav(src);
  const mono = Float32Array.from(w.chans[0], (_, i) => w.chans.reduce((a, c) => a + c[i], 0) / w.chans.length);
  let y = resample(mono, w.sr, SR);
  const loud = y.reduce((a, v) => Math.max(a, Math.abs(v)), 0);
  const thr = loud * 10 ** (-30 / 20); // 가장 큰 소리보다 30dB 작으면 묵음
  let s = 0;
  let e = y.length - 1;
  while (s < e && Math.abs(y[s]) < thr) s++;
  while (e > s && Math.abs(y[e]) < thr) e--;
  y = y.slice(s, e + 1);
  const peak = y.reduce((a, v) => Math.max(a, Math.abs(v)), 1e-9);
  writeWav(dst, [y.map((v) => (v / peak) * 0.9)], SR);
  return dst;
}

const describe = (p: string): string => {
  const w = readWav(p);
  return `${String(w.sr).padStart(6)} Hz | ${w.chans.length}ch | ${w.bits}bit | ${(w.chans[0].length / w.sr).toFixed(2)}초 | ${(statSync(p).size / 1024).toFixed(1)} KB`;
};

// 입력 세 가지: 앞뒤에 0.3초 묵음이 붙은 말소리
function padded(sr: number): Float32Array {
  const v = synthVoice(1.5, 140, 0, sr);
  const z = Math.round(0.3 * sr);
  const out = new Float32Array(v.length + 2 * z);
  out.set(v.map((x) => 0.2 * x), z);
  return out;
}
const hq = padded(44100);
writeWav("in_hq.wav", [hq, hq.map((v) => 0.6 * v)], 44100); // 44.1kHz stereo
writeWav("in_8k.wav", [padded(8000)], 8000); // 8kHz mono (전화)
writeWav("in_48k.wav", [padded(48000)], 48000, true); // 48kHz 32bit float

let ok = true;
for (const src of ["in_hq.wav", "in_8k.wav", "in_48k.wav"]) {
  const out = makeModelReady(src, `ready_${src}`);
  console.log(`[전] ${src.padEnd(12)} ${describe(src)}`);
  console.log(`[후] ${out.padEnd(18)} ${describe(out)}\n`);
  const o = readWav(out);
  const i = readWav(src);
  const peak = o.chans[0].reduce((a, v) => Math.max(a, Math.abs(v)), 0);
  ok = ok && o.sr === 16000 && o.chans.length === 1 && o.bits === 16 && o.chans[0].length / o.sr < i.chans[0].length / i.sr - 0.3 && Math.abs(peak - 0.9) < 0.01;
}
check(ok, "모두 16kHz · mono · 16bit, 묵음이 잘려 짧아지고 가장 큰 소리가 0.9여야 해요.");
